),
affected_users as (
    select distinct user_id
    from affected
),
user_trips as (
    select
        s.user_id,
        s.trip_id,
        bool_or(s.cancellation) as cancellation_recorded
    from sessions as s
    inner join affected_users as u
        on s.user_id = u.user_id
    where s.trip_id is not null
    group by s.user_id, s.trip_id
),
overlap_counts as (
    select
        a.trip_id,
        a.user_id,
        a.check_in_time,
        count(distinct h.trip_id) as other_overlapping_bookings,
        count(distinct h.trip_id) filter (
            where t.cancellation_recorded is false
        ) as overlaps_without_recorded_cancellation
    from affected as a
    left join user_trips as t
        on a.user_id = t.user_id
        and a.trip_id <> t.trip_id
    left join hotels as h
        on t.trip_id = h.trip_id
        and h.check_out_time > h.check_in_time
        and h.check_in_time <= a.check_in_time
        and h.check_out_time > a.check_in_time
    group by a.trip_id, a.user_id, a.check_in_time
)
select
    count(*) as affected_hotel_records,
    count(*) filter (
        where other_overlapping_bookings > 0
    ) as with_other_overlapping_booking,
    count(*) filter (
        where overlaps_without_recorded_cancellation > 0
    ) as with_overlap_without_recorded_cancellation,
    count(*) filter (
        where other_overlapping_bookings = 0
    ) as without_overlapping_booking
from overlap_counts;
